"""Migrated Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal
from typing import Any


def _text(value: Any) -> str:
    return "" if value is None else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _error(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {"code": code, "message": message, "severity": severity}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    errors: list[dict] = []
    old_record = old if event == "UPDATE" and old is not None else {}

    # ACC-001
    if event in ("INSERT", "UPDATE"):
        if len(_text(record.get("ACCT_NM", ""))) < 2:
            errors.append(_error("E1001", "Account name too short"))

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _text(record.get("ACCT_TYP", "")) not in ("C", "P", "R", "X"):
            errors.append(_error("E1002", "Invalid account type"))

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        if _number(record.get("ANN_REV", "")) < 0:
            errors.append(_error("E1003", "Annual revenue negative"))

    # ACC-004
    if event == "UPDATE":
        if (
            _text(old_record.get("CRED_HOLD", "")) == "Y"
            and _text(record.get("CRED_HOLD", "")) == "N"
            and _number(record.get("CRED_LIMIT", "")) <= 0
        ):
            errors.append(
                _error("E1004", "Cannot release credit hold with zero credit limit")
            )

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if len(_text(record.get("REGION_CD", ""))) != 3:
            errors.append(
                _error("E1005", "Region code must be 3 chars", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
